INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(13201, 'Psalms 20:7', 'Psalms', 20, 7, '&nbsp;څوک فخر کوى په جنګى ګاډو او څوک په آسونو، خو مونږ د مالِک خُدائ د خپل خُدائ پاک په نوم فخر کوُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13202, 'Psalms 20:8', 'Psalms', 20, 8, '&nbsp;دا قومونه به په ګوډو شى او راوبه غورزيږى، خو مونږ به راپاڅو او ټينګ به ودرېږو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13203, 'Psalms 20:9', 'Psalms', 20, 9, '&nbsp;ورکړه فتح زمونږ بادشاه له، اے مالِکه خُدايه، کله چې تا ته سوال کوُو مونږ ته جواب راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13204, 'Psalms 21:1', 'Psalms', 21, 1, '&nbsp;مالِکه خُدايه، بادشاه ستا په طاقت څنګه خوشحالى کوى. ځکه چې هغه ستا په فتح ورکولو څومره لويه خوشحالى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13205, 'Psalms 21:2', 'Psalms', 21, 2, '&nbsp;تا دے ورکړے د هغۀ د زړۀ ارمان تا نۀ دے رد کړے د هغۀ د خولې بيان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13206, 'Psalms 21:3', 'Psalms', 21, 3, '&nbsp;تا هغه په ډېرو کاميابو او برکتونو معمور کړے دے تاج دې د خالص سرو زرو ورپه سر کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13207, 'Psalms 21:4', 'Psalms', 21, 4, '&nbsp;چې د ژوند سوال يې له تا کړے دے نو تا يې سوال قبول کړے دے نو د تل دپاره تا د هغۀ ژوند اوږد کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13208, 'Psalms 21:5', 'Psalms', 21, 5, '&nbsp;ستا په خلاصون او مدد هغۀ وموندو عزت، تا هغۀ له ورکړو شُهرت، شان او شوکت.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13209, 'Psalms 21:6', 'Psalms', 21, 6, '&nbsp;هغۀ له دې ورکړے برکت نۀ ختمېدونکے ورکړے خپل ديدار دې ورته زړۀ خوشحالوونکے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13210, 'Psalms 21:7', 'Psalms', 21, 7, '&nbsp;ځکه چې بادشاه په مالِک خُدائ باندې ايمان لرى، د خُدائ تعالىٰ په مينه هغه به تل د تيندکونو نه بچ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13211, 'Psalms 21:8', 'Psalms', 21, 8, '&nbsp;نو تۀ به خپل ټول دشمنان راګېر کړې، څوک چې درنه نفرت کوى نو هغه هر يو به په خپل ښى لاس راګېر کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13212, 'Psalms 21:9', 'Psalms', 21, 9, '&nbsp;کله چې تۀ راښکاره شې په هغوئ به د بټۍ په شان اور بل کړې. مالِکه خُدايه ستا د غضب اور به دوئ تير کړى او ستا اور به يې تباه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13213, 'Psalms 21:10', 'Psalms', 21, 10, '&nbsp;تۀ به د هغوئ اولاد د زمکې نه جارُو کړې، تۀ به هغوئ له نسل ورنۀ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13214, 'Psalms 21:11', 'Psalms', 21, 11, '&nbsp;کۀ څۀ هم بدې ارادې لرى تا ته او نېتُونه يې خراب شى خو کاميابه به هيڅکله د هغوئ منصوبې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13215, 'Psalms 21:12', 'Psalms', 21, 12, '&nbsp;تۀ به کړې هغوئ دې ته جوړ چې په شا شى دوئ چې کله ستا د ليندې غشو ته مخامخ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13216, 'Psalms 21:13', 'Psalms', 21, 13, '&nbsp;راپاڅه اے مالِکه خُدايه، په خپل ټول قدرت، مونږ به ووايو سندرې او ثناء ستا د زور او طاقت.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13217, 'Psalms 22:1', 'Psalms', 22, 1, '&nbsp;اے زما خُدايه، اے زما خُدايه، زۀ دې ولې پرېښودلم؟ تۀ ولې رانه لرې شوے يې او د مدد فرياد مې نۀ اورې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13218, 'Psalms 22:2', 'Psalms', 22, 2, '&nbsp;په ورځ کښې تا ته فرياد کوم زما خُدايه خو تۀ جواب نۀ راکوې، هره شپه تۀ زما آواز اورې، خو ما ته هيڅ آرام رانۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13219, 'Psalms 22:3', 'Psalms', 22, 3, '&nbsp;خو ستا پاکه هستى پاس په تخت، اِسرائيليان کوى ستا ثناء صِفت.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13220, 'Psalms 22:4', 'Psalms', 22, 4, '&nbsp;زمونږ پلار نيکۀ په تا لرلو ايمان، او تۀ شوې د هغوئ نګهبان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13221, 'Psalms 22:5', 'Psalms', 22, 5, '&nbsp;دوئ تا ته فريادونه وکړل تا خلاصون ورکړو، هغوئ مايوسه نۀ شول په تا چې چا اطمينان وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13222, 'Psalms 22:6', 'Psalms', 22, 6, '&nbsp;خو زۀ چينجے يم او انسان نۀ يم، سپک راته ګورى د ټولو د خندا يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13223, 'Psalms 22:7', 'Psalms', 22, 7, '&nbsp;څوک چې راته ګورى خندا راپورې کوى، دوئ سرونه خوځوى راته سپک ګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13224, 'Psalms 22:8', 'Psalms', 22, 8, '&nbsp;دوئ وائى چې، ”لرلو يې په مالِک خُدائ اطمينان آيا دا هغه څوک دے، خو مالِک خُدائ دې اوس دے بچ کړى. ځکه چې مالِک خُدائ بې‌شانه مينه ورسره کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13225, 'Psalms 22:9', 'Psalms', 22, 9, '&nbsp;تا د مور د خېټې نه په سلامتۍ رابهر کړم، ما له دې باور راکړو زۀ دې د مور په سينه لوئ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13226, 'Psalms 22:10', 'Psalms', 22, 10, '&nbsp;د پېدايښت نه ستا لاسونو ته وسپارلے شوم، تۀ زما خُدائ يې د کوم وخت نه چې پېدا شوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13227, 'Psalms 22:11', 'Psalms', 22, 11, '&nbsp;زما نه لرې مۀ ودرېږه ځکه چې مصيبت را په سر دے، او ستا نه علاوه بل څوک نشته چې وى زما مددګار.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13228, 'Psalms 22:12', 'Psalms', 22, 12, '&nbsp;د ډېرو غوَيانو په شان دشمنانو راګېر کړے يم، لکه د بسن د يروونکو غوَيانو غوندې يې ګېر کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13229, 'Psalms 22:13', 'Psalms', 22, 13, '&nbsp;زما خلاف يې د زمرو په شان خپلې خولې وازې کړې دى په غړمبار سره ما څيرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13230, 'Psalms 22:14', 'Psalms', 22, 14, '&nbsp;توئ شوے يم زۀ لکه اوبو په شان، هډوکى د جوړونو نه مې شوى دى بې‌ځايه. زړۀ زما ويلى شو د موم په شان،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13231, 'Psalms 22:15', 'Psalms', 22, 15, '&nbsp;ټول زور مې خُشک شو د خاورين لوښى په شان، ژبه مې تالو پورې شوه چسپان، په خاورو کښې تا پرېښے يم د مړى په شان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13232, 'Psalms 22:16', 'Psalms', 22, 16, '&nbsp;د سپو په شان دشمنانو راګېر کړے يم، د بدکارانو قبيلې راګېر کړے يم، دوئ ‎په پښو لاسو زخمى کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13233, 'Psalms 22:17', 'Psalms', 22, 17, '&nbsp;ټول هډوکى خپل شمېرلے شم، دشمنان راته راګورى او په ما خوشحاليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13234, 'Psalms 22:18', 'Psalms', 22, 18, '&nbsp;هغوئ په خپلو کښې تقسيموى جامې زما په خپلو کښې خسڼے پرې وباسى په جامو زما.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13235, 'Psalms 22:19', 'Psalms', 22, 19, '&nbsp;اے مالِکه خُدايه زما نه لرې مۀ ودرېږه، تۀ زما زور او طاقت يې زر زما مدد دپاره راشه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13236, 'Psalms 22:20', 'Psalms', 22, 20, '&nbsp;ما د تُورې د خولې نه بچ کړه، د دغه سپو نه زما قيمتى ژوند بچ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13237, 'Psalms 22:21', 'Psalms', 22, 21, '&nbsp;د زمرو د خولې نه ما راوباسه، او ما د ځنګلى غوَيانو د ښکرو نه په امان کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13238, 'Psalms 22:22', 'Psalms', 22, 22, '&nbsp;زۀ به خپلو خلقو ته ستا د نوم لوئى بيان کړم، ستا ثناء صِفت به زۀ د جماعت په مينځ کښې وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13239, 'Psalms 22:23', 'Psalms', 22, 23, '&nbsp;تاسو څوک چې د خُدائ نه يرېږئ د مالِک خُدائ ستائينه وکړئ، اے د يعقوب اولاده، تاسو هغۀ له عزت ورکړئ، اے بنى اِسرائيلو تاسو ټول د هغۀ عزت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13240, 'Psalms 22:24', 'Psalms', 22, 24, '&nbsp;ځکه هغۀ نۀ د حاجتمندانو درد ته سپک وکتل، او نۀ هغۀ د هغوئ ضرورتونو ته شا کوى نو هغه د هغوئ فريادونه اورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13241, 'Psalms 22:25', 'Psalms', 22, 25, '&nbsp;زۀ به په لويه ډله کښې ستا ثناء صِفت وکړم، د مؤمنانو په وړاندې به زۀ خپل نذرونه پېش کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13242, 'Psalms 22:26', 'Psalms', 22, 26, '&nbsp;غريبانان به ماړۀ او مطمئن شى، د مالِک خُدائ ټول لټوونکى به ثناء خوان شى د هغوئ زړونه دې د تل دپاره خوشحاله وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13243, 'Psalms 22:27', 'Psalms', 22, 27, '&nbsp;ټوله دُنيا به مالِک خُدائ ياد کړى او هغۀ ته به راوګرځى، د دُنيا ټول قومونه او هر خاندان به هغۀ ته سجده وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13244, 'Psalms 22:28', 'Psalms', 22, 28, '&nbsp;ځکه چې مالِک خُدائ بادشاه دے او د هغۀ په قومونو حکومت دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13245, 'Psalms 22:29', 'Psalms', 22, 29, '&nbsp;د دُنيا ټول کبرژن به هغۀ ته په تعظيم شى، څوک چې فانى دى هغه ټول به ورته په سجده شى هغوئ به خپل ځانونه ژوندى ساتلے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13246, 'Psalms 22:30', 'Psalms', 22, 30, '&nbsp;راتلونکے نسل به يې خِدمت کوى، د مالِک خُدائ بيان به راتلونکى نسل ته کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13247, 'Psalms 22:31', 'Psalms', 22, 31, '&nbsp;هغه څوک چې لا پېدا نۀ دى د هغۀ د خلاصون نه به خبر شى دوئ به د هغۀ د ټولو کارنامو نه خبر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13248, 'Psalms 23:1', 'Psalms', 23, 1, '&nbsp;مالِک خُدائ دے شپون زما، نو د هيڅ څيز حاجت نشته دے زما.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13249, 'Psalms 23:2', 'Psalms', 23, 2, '&nbsp;راکوى آرام په شين چمن کښې ما له، بوځى مې هغه د آرامو اوبو خوا له.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13250, 'Psalms 23:3', 'Psalms', 23, 3, '&nbsp;هغه راکوى تازه او نوے قوت ما له، په نېغه لار مې بيائى د خپل نوم دپاره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13251, 'Psalms 23:4', 'Psalms', 23, 4, '&nbsp;کۀ څۀ هم د مرګ وادۍ نه زۀ تېرېږم، خو تۀ زما په څنګ يې نو نۀ يرېږم، ستا په چوکه او امسا زما تسلى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13252, 'Psalms 23:5', 'Psalms', 23, 5, '&nbsp;تۀ زما د دشمنانو په وړاندې تياروې ډېر خوراک ما له، تۀ مې سر په تېلو غوړوې نو په دې عزت راکوې ما له، تۀ د خپل برکت نه تر څنډو ډکوې پياله ما له.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13253, 'Psalms 23:6', 'Psalms', 23, 6, '&nbsp;بې‌شکه ستا نېکى او مينه به وى زما د ټول ژوند دپاره، زۀ به د مالِک خُدائ کور کښې اوسېږم د تل دپاره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13254, 'Psalms 24:1', 'Psalms', 24, 1, '&nbsp;دا دُنيا د مالِک خُدائ ده او هر څۀ چې په دې کښې دى، دا ټوله دُنيا او انسانان څوک چې په دې کښې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13255, 'Psalms 24:2', 'Psalms', 24, 2, '&nbsp;په دريابونو باندې اېښى مالِک خُدائ د زمکې بنيادونه دى، دا زمکه يې په سمندر باندې آباده کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13256, 'Psalms 24:3', 'Psalms', 24, 3, '&nbsp;د مالِک خُدائ غر ته څوک ورختلے شى؟ او څوک د هغۀ مقدس ځائ کښې ودرېدلے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13257, 'Psalms 24:4', 'Psalms', 24, 4, '&nbsp;يواځې هغه څوک چې يې زړونه او لاسونه پاک وى، څوک چې د بُتانو عبادت نۀ کوى، او هيڅکله د دروغو قسمونه نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13258, 'Psalms 24:5', 'Psalms', 24, 5, '&nbsp;دوئ ته به د مالِک خُدائ برکت مِلاو شى، او خپل خلاصونکى خُدائ پاک نه به صداقت حاصل کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13259, 'Psalms 24:6', 'Psalms', 24, 6, '&nbsp;او هم داسې خلق ستا د مخ لټون کوى، اے د يعقوب خُدايه، دوئ به ستا طلب کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13260, 'Psalms 24:7', 'Psalms', 24, 7, '&nbsp;اے زړو دروازو کولاو شئ، ابدى ورونو خلاص شئ، چې د جلال بادشاه دننه درشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13261, 'Psalms 24:8', 'Psalms', 24, 8, '&nbsp;هغه د جلال بادشاه څوک دے؟ هغه دے مالِک خُدائ چې ډېر قوى او زورَور دے، هغه مالِک خُدائ چې په جنګ کښې تکړه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13262, 'Psalms 24:9', 'Psalms', 24, 9, '&nbsp;اے زړو دروازو کولاو شئ، ابدى وروڼو خلاص شئ، چې د جلال بادشاه دننه درشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13263, 'Psalms 24:10', 'Psalms', 24, 10, '&nbsp;هغه د جلال بادشاه څوک دے؟ هغه ربُ الافواج دے، هغه د جلال بادشاه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13264, 'Psalms 25:1', 'Psalms', 25, 1, '&nbsp;زما مالِکه خُدايه، زۀ دُعا غواړم له تا،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13265, 'Psalms 25:2', 'Psalms', 25, 2, '&nbsp;اے زما پاکه خُدايه، زۀ توکل کوم په تا. ما شرمنده کېدو نه بچ کړه، مۀ پرېږده چې دشمنان کامياب شى په ما.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13266, 'Psalms 25:3', 'Psalms', 25, 3, '&nbsp;هيڅکله شرمنده به نۀ شى هغه څوک چې کوى يقين په تا، خو شرميږى به هغوئ چې د نورو سره کوى دوکه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13267, 'Psalms 25:4', 'Psalms', 25, 4, '&nbsp;اے مالِکه خُدايه، ما ته خپلې لارې وښايه، خپلې لارې راته وښايه چې زۀ په هغې لاړ شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13268, 'Psalms 25:5', 'Psalms', 25, 5, '&nbsp;تۀ ما د خپل حقيقت خوا له بوځه او هم درس راکړه ما له، او هر وخت زۀ توکل کوم په تا اے زما خلاصونکى خُدايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13269, 'Psalms 25:6', 'Psalms', 25, 6, '&nbsp;اے مالِکه خُدايه هغه مينه او رحم دې در په ياد کړه خپله، چې کوله دې د ازله تا په خپله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13270, 'Psalms 25:7', 'Psalms', 25, 7, '&nbsp;زما د ځوانۍ غلطۍ او ګناه مۀ يادوه خو ما د خپلې بې‌بها مينې په وجه يادوه، ځکه چې تۀ مهربان يې اے مالِکه خُدايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13271, 'Psalms 25:8', 'Psalms', 25, 8, '&nbsp;ښۀ مې مالِک خُدائ دے سم کارونه کوى، څوک چې وى بې‌لارې هغوئ ته نېغه لار سموى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13272, 'Psalms 25:9', 'Psalms', 25, 9, '&nbsp;هغه عاجزان په سمه لار روانوى، او خپله لار هغوئ ته ور زده کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13273, 'Psalms 25:10', 'Psalms', 25, 10, '&nbsp;د مالِک خُدائ ټولې لارې دى ډکې د وفا او د مينې، د هغه چا دپاره چې ساتى د هغۀ د لوظ ټولې غوښتنې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13274, 'Psalms 25:11', 'Psalms', 25, 11, '&nbsp;اے مالِکه خُدايه، د خپل پاک نوم د خاطره، راوبخښه کۀ هر څومره زما ګناه ده لويه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13275, 'Psalms 25:12', 'Psalms', 25, 12, '&nbsp;څوک دى هغوئ چې د مالِک خُدائ نه يره کوى؟ هغه به دوئ ته هغه لار وښائى کومه چې دوئ دپاره غوره کول دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13276, 'Psalms 25:13', 'Psalms', 25, 13, '&nbsp;هغوئ به خپل ژوند په خير تېروى، د هغۀ اولاد ته به زمکه په ميراث کښې ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13277, 'Psalms 25:14', 'Psalms', 25, 14, '&nbsp;مالِک خُدائ د هغه چا ملګرے دے څوک چې د هغۀ نه يريږى، هغوئ ته به د خپل لوظ شرطونه ورزده کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13278, 'Psalms 25:15', 'Psalms', 25, 15, '&nbsp;زما نظر به همېشه د مالِک خُدائ طرف ته وى، هم هغه ما د دشمنانو د دام نه خلاصوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13279, 'Psalms 25:16', 'Psalms', 25, 16, '&nbsp;او خپل فضل په ما وکړه زما طرف ته راوګرځه، ځکه زۀ يواځې شوے يم بد حاله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13280, 'Psalms 25:17', 'Psalms', 25, 17, '&nbsp;د بد نه بدتر شول زما غمونه، خلاص مې کړه تکليفونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13281, 'Psalms 25:18', 'Psalms', 25, 18, '&nbsp;زما غمونو او مصيبتونو ته توجو ورکړه او زما ټول ګناهونه ما ته معاف کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13282, 'Psalms 25:19', 'Psalms', 25, 19, '&nbsp;ګوره څومره ډيريږى دشمنان زما ګوره چې دوئ څومره کرکه کوى له ما.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13283, 'Psalms 25:20', 'Psalms', 25, 20, '&nbsp;زما ژوند د دوئ نه په امان کړه ما وساته، ما مۀ شرموه چې راوړې مې ده پناه تا ته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13284, 'Psalms 25:21', 'Psalms', 25, 21, '&nbsp;زما راستى زما نېکى دې پام وکړى په ما، ځکه چې په تا توکل کړے دے ما.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13285, 'Psalms 25:22', 'Psalms', 25, 22, '&nbsp;اے پاکه خُدايه، بنى اِسرائيل بچ کړه، د ټولو مشکلاتو نه يې خلاص کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13286, 'Psalms 26:1', 'Psalms', 26, 1, '&nbsp;اے مالِکه خُدايه، زما د بې‌ګناهۍ په حقله تاسو فېصله وکړئ، ځکه چې ما تل نېکى کړې ده، ما په مالِک خُدائ بې‌شکه باور کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13287, 'Psalms 26:2', 'Psalms', 26, 2, '&nbsp;اے مالِکه خُدايه په ما آزمېښت وکړه او تيار مې کړه، زما د زړۀ او خيالونو آزمېښت وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13288, 'Psalms 26:3', 'Psalms', 26, 3, '&nbsp;خو زۀ ستا د بې‌شانه مينې نه همېشه خبر يم، نو ځکه زۀ ستا د حقيقت په مطابق ژوند تېروم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13289, 'Psalms 26:4', 'Psalms', 26, 4, '&nbsp;زۀ د دروغژنو خلقو سره نۀ کښېنم، نۀ د مُنافقانو سره په لاره ځم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13290, 'Psalms 26:5', 'Psalms', 26, 5, '&nbsp;د بدعملو د محفل نه زۀ نفرت کوم او نۀ زۀ د شريرانو ملګرتيا کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13291, 'Psalms 26:6', 'Psalms', 26, 6, '&nbsp;زۀ خپل لاسونه د ګناه نه وينځم، اے مالِکه خُدايه، نو ستا قربان‌ګاه نه به طواف کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13292, 'Psalms 26:7', 'Psalms', 26, 7, '&nbsp;زۀ به د شکرانې سندرې وايم او ستا ټول عجيبه کارونه به وايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13293, 'Psalms 26:8', 'Psalms', 26, 8, '&nbsp;زۀ مينه کوم مالِکه خُدايه ستا مقدس کور سره، چرته چې ستا جلالى حضور اوسيږى هغه ځائ سره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13294, 'Psalms 26:9', 'Psalms', 26, 9, '&nbsp;ما د ګناهګارانو سره مۀ حسابوه، ما د قاتلانو سره مۀ مجرم کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13295, 'Psalms 26:10', 'Psalms', 26, 10, '&nbsp;په ناپاکه منصوبو د هغوئ لاسونه سخا دى، د رشوت نه ډک هر وخت د هغوئ لاسونه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13296, 'Psalms 26:11', 'Psalms', 26, 11, '&nbsp;خو زۀ داسې نۀ يم، زۀ په دُنيا کښې پاک اوسېږم، په ما شه مِهربانه او ما بچ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13297, 'Psalms 26:12', 'Psalms', 26, 12, '&nbsp;زۀ اوس په هوار مېدان ولاړ يم، زۀ به د ټول جماعت په وړاندې د مالِک خُدائ ثناء صِفت وايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13298, 'Psalms 27:1', 'Psalms', 27, 1, '&nbsp;مالِک خُدائ دے زما خلاصون او زما رڼا نو بيا زۀ ولې يره وکړم د چا؟ او مالِک خُدائ دے زما د ژوند قلعه نو بيا به زۀ ولې يره وکړم د چا؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13299, 'Psalms 27:2', 'Psalms', 27, 2, '&nbsp;چې کله ما ختمول غواړى بدکاران او حمله راباندې وکړى زما دشمنان، تيندک به وخورى او راګزار به شى زما دشمنان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13300, 'Psalms 27:3', 'Psalms', 27, 3, '&nbsp;هر څو کۀ رانه تاو شى ګېرچاپېره لښکرې، زړۀ کښې يره نۀ لرم. کۀ شروع شى زما خلاف جنګونه، خو زۀ به خاطر جمع يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');